interface Notifier {
    void send(String message);
}

// Depend d'une abstraction (couplage de donnees), pas d'un detail concret
class AlertService {
    private final Notifier notifier;
    AlertService(Notifier notifier) { // injection par le constructeur
        this.notifier = notifier;
    }
    void raise(String message) {
        notifier.send(message);
    }
}

// Une implementation concrete est branchee au bord, pas au coeur
class SmtpNotifier implements Notifier {
    private final SmtpClient client = new SmtpClient();
    public void send(String message) { client.sendEmail(message); }
}
